<?php $page_title='การคืนสินค้าของฉัน';require_once __DIR__.'/includes/auth_check.php';requireLogin();require_once __DIR__.'/config/database.php';$db=(new Database())->getConnection();$stmt=$db->prepare('SELECT r.*,o.order_no,o.total_amount FROM return_requests r JOIN orders o ON o.id=r.order_id WHERE r.user_id=? ORDER BY r.id DESC');$stmt->execute([(int)$_SESSION['user_id']]);$returns=$stmt->fetchAll();require_once __DIR__.'/includes/header.php';?>
<div class="container" style="margin:36px auto 70px;max-width:900px"><div style="display:flex;justify-content:space-between;align-items:center;gap:16px"><h1><i class="fa-solid fa-arrow-rotate-left"></i> การคืนสินค้า</h1><a class="btn btn-outline" href="<?php echo BASE_URL;?>my-orders.php">คำสั่งซื้อของฉัน</a></div><div style="display:grid;gap:14px;margin-top:24px"><?php if(!$returns):?><section style="background:#fff;border:1px solid var(--border-color);padding:40px;text-align:center">ยังไม่มีคำขอคืนสินค้า</section><?php endif;?><?php foreach($returns as $r):?><article style="background:#fff;border:1px solid var(--border-color);padding:22px"><div style="display:flex;justify-content:space-between;gap:12px"><strong><?php echo e($r['order_no']);?></strong><span class="status-badge <?php echo e($r['status']);?>"><?php echo e($r['status']);?></span></div><p><?php echo nl2br(e($r['reason']));?></p><?php if($r['admin_note']):?><small>หมายเหตุ: <?php echo e($r['admin_note']);?></small><?php endif;?></article><?php endforeach;?></div></div><?php require_once __DIR__.'/includes/footer.php';?>
